CREATE TABLE vessels (
  vessel_id INT,
  vessel_name TEXT,
  class_type TEXT
);

CREATE TABLE docking_bays (
  bay_id INT,
  station_name TEXT,
  capacity INT,
  status TEXT
);

SELECT v.vessel_name, c.cargo_type, c.mass_tons
FROM vessels v
LEFT JOIN cargo c ON v.vessel_id = c.vessel_id;

SELECT vessel_id, SUM(mass_tons) as total FROM cargo
GROUP BY vessel_id
HAVING total = (SELECT MAX(total_mass) FROM (SELECT SUM(mass_tons) as total_mass FROM cargo GROUP BY vessel_id));

WITH vessel_load AS (
  SELECT vessel_id, SUM(mass_tons) as total_mass FROM cargo GROUP BY vessel_id
)
SELECT v.vessel_name, vl.total_mass
FROM vessels v
JOIN vessel_load vl ON v.vessel_id = vl.vessel_id;

SELECT c.name, c.vessel_id
FROM crew c
WHERE EXISTS (
  SELECT 1 FROM cargo ca WHERE ca.vessel_id = c.vessel_id
);

WITH crew_counts AS (
  SELECT vessel_id, COUNT(*) as crew_count FROM crew GROUP BY vessel_id
),
cargo_totals AS (
  SELECT vessel_id, SUM(mass_tons) as total_cargo FROM cargo GROUP BY vessel_id
)
SELECT v.vessel_name, cc.crew_count, ct.total_cargo
FROM vessels v
LEFT JOIN crew_counts cc ON v.vessel_id = cc.vessel_id
LEFT JOIN cargo_totals ct ON v.vessel_id = ct.vessel_id;
